public List<QueryContainer> CreateQueryContainerList(string prefix, string Document, List<QueryContainer> qlist)
{
    var result = qlist;
    if (Document.IndexOf("[") == 0)
    {
        var results = new List<object>();
        var documents = System.Text.Json.JsonSerializer.Deserialize<object[]>(Document);
        for (var i = 0; i < documents.Length; i++)
        {
            result = CreateQueryContainerList(prefix, documents[i].ToString(), result);
        }
        return result;
    }
    else
    {
        if (Document.IndexOf("{") == 0)
        {
            Dictionary<string, object> myObject = new Dictionary<string, object>();
            dynamic stuff = JObject.Parse(Document.ToString());
            foreach (Newtonsoft.Json.Linq.JProperty jproperty in stuff)
            {
                if (jproperty.Value.ToString().IndexOf("[") >= 0 || jproperty.Value.ToString().IndexOf("{") >= 0)
                {

                    var newPrefix = prefix + jproperty.Name;
                    if (prefix != "")
                    {
                        newPrefix = prefix + "." + jproperty.Name;
                    }
                    result = CreateQueryContainerList(newPrefix, jproperty.Value.ToString(), result);

                }
                else
                {
                    var newPrefix = prefix + jproperty.Name;
                    if (prefix != "")
                    {
                        newPrefix = prefix + "." + jproperty.Name;
                    }
                    var value = jproperty.Value.ToString();
                    if (jproperty.Value.Type == JTokenType.String)
                    {
                        QueryStringQuery query = new QueryStringQuery() { DefaultField = newPrefix, Query = $"*{value}*" };   
                        result.Add(query);
                    }
                    else
                    {
                        QueryStringQuery query = new QueryStringQuery() { DefaultField = newPrefix, Query = $"{value}" };
                        result.Add(query);
                    }
                }
            }
            return result;
        }
        else
        {
            QueryStringQuery query = new QueryStringQuery() { DefaultField = prefix, Query = $"{Document}" };
            result.Add(query);
            return result;
        }
    }
}


public object ParseObjectAlternative(object Document)
{
    if (Document.ToString().IndexOf("[") == 0)
    {
        var results = new List<object>();
        var documents = System.Text.Json.JsonSerializer.Deserialize<object[]>(Document.ToString());
        for (var i = 0; i < documents.Length; i++)
        {
            results.Add(ParseObjectAlternative(documents[i]));
        }
        return results.ToArray();
    }
    else
    {
        if (Document.ToString().IndexOf("{") == 0)
        {
            Dictionary<string, object> myObject = new Dictionary<string, object>();
            dynamic stuff = JObject.Parse(Document.ToString());
            foreach (Newtonsoft.Json.Linq.JProperty jproperty in stuff)
            {
                if (jproperty.Value.ToString().IndexOf("[") >= 0 || jproperty.Value.ToString().IndexOf("{") >= 0)
                {
                    myObject[jproperty.Name] = ParseObjectAlternative(jproperty.Value);
                }
                else
                {
                    myObject[jproperty.Name] = ParseJpropertyObject(jproperty);
                }
            }
            return myObject;
        }
        else
        {

            return ParseSimpleObject(Document);
        }
    }
}

public object ParseJpropertyObject(JProperty jproperty)
{
    switch(jproperty.Value.Type)
    {
        case JTokenType.String:
            return jproperty.Value.ToString();
        case JTokenType.Date:
